# LangChain needs extra installs and an LLM API, which this sandbox does not have.
# These small stand-ins behave the same way: @tool turns a function into a Tool with a
# name, a description (its docstring) and .invoke(), and FakeReActLLM answers in the
# ReAct format (Thought / Action / Action Input ... Final Answer).
class Tool:
    def __init__(self, func):
        self.func = func
        self.name = func.__name__
        self.description = (func.__doc__ or "").strip()

    def invoke(self, tool_input):
        return self.func(tool_input)


def tool(func):
    """Mini version of langchain's @tool decorator."""
    return Tool(func)


class FakeReActLLM:
    """Scripted LLM: decides the next step from the Observations already in the prompt."""

    def invoke(self, prompt):
        observations = [line[len("Observation: "):] for line in prompt.splitlines()
                        if line.startswith("Observation: ")]
        if len(observations) == 0:
            return "Thought: First count the words.\nAction: word_count\nAction Input: Hello world from PyMasters"
        if len(observations) == 1:
            return "Thought: Now reverse the text.\nAction: reverse_text\nAction Input: Python"
        return f"Thought: I have both results.\nFinal Answer: {observations[0]} words; reversed: {observations[1]}"


@tool
def word_count(text):
    """Count the number of words in the given text."""
    return str(len(text.split()))


@tool
def reverse_text(text):
    """Reverse the given text string."""
    return text[::-1]


def parse_action(llm_output):
    """Return (tool_name, tool_input) from the 'Action:' and 'Action Input:' lines."""
    name, tool_input = None, None
    for line in llm_output.splitlines():
        if line.startswith("Action Input:"):
            tool_input = line[len("Action Input:"):].strip()
        elif line.startswith("Action:"):
            name = line[len("Action:"):].strip()
    return name, tool_input


def run_agent(question, llm, tools, max_steps=5):
    """The ReAct loop: think -> act -> observe, until a Final Answer."""
    prompt = f"Question: {question}\n"
    for _ in range(max_steps):
        output = llm.invoke(prompt)
        prompt += output + "\n"
        if "Final Answer:" in output:
            return output.split("Final Answer:", 1)[1].strip()
        name, tool_input = parse_action(output)
        result = tools[name].invoke(tool_input)
        prompt += f"Observation: {result}\n"
    return None


print(word_count.invoke("Hello world from PyMasters"))
print(reverse_text.invoke("Python"))
tools = {t.name: t for t in [word_count, reverse_text]}
print(run_agent("Count the words in 'Hello world from PyMasters' and reverse 'Python'", FakeReActLLM(), tools))
